CREATE POLICY "product media own insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'product-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "product media own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'product-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "product media own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'product-media' AND (storage.foldername(name))[1] = auth.uid()::text);